const b = $input.first().json.body || {};
const msg = String(b.message || '').toLowerCase();
const lang = b.lang === 'ua' ? 'ua' : 'ru';
let reply;
if (/привет|привіт|hello|hi/.test(msg)) {
  reply = lang === 'ua' ? 'Привіт! Я Квантик. Питай про урок.' : 'Привет! Я Квантик. Спроси что-нибудь по уроку.';
} else if (/не понимаю|не зрозуміло|помоги|допоможи|help/.test(msg)) {
  reply = lang === 'ua' ? 'Добре, розберімо крок за кроком. Що саме незрозуміло?' : 'Хорошо, разберём шаг за шагом. Что именно непонятно?';
} else if (b.lessonId) {
  reply = lang === 'ua' ? ('Тема уроку: ' + b.lessonId + '. Спробуй сформулювати точніше, що саме запитати.') : ('Тема урока: ' + b.lessonId + '. Попробуй сформулировать точнее, что спросить.');
} else {
  reply = lang === 'ua' ? 'Я на зв\'язку. Постав питання про урок — і я підкажу.' : 'Я на связи. Задай вопрос по уроку — и я подскажу.';
}
return [{ json: { reply, lessonId: b.lessonId || null, lang } }];
